preConditions.sqlCheck:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM ndr_code_set
WHERE code_description = 'ABC+3TC(or FTC)+DTG' AND code = '1c';

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM hiv_regimen_resolver
WHERE regimen = 'ABC+3TC(or FTC)+DTG';

changeSet.sql:
UPDATE hiv_regimen_resolver
SET regimen = 'ABC+3TC+DTG'
WHERE regimen = 'ABC+3TC(or FTC)+DTG';

DELETE FROM ndr_code_set
WHERE code = '5c'
   OR code_description = 'TDF +-3TC + ATV/r_old'
   OR code_description = 'TDF+3TC+ATV/r';

